import pytest
from fastapi import FastAPI, Depends, Security
from fastapi.dependencies import SecurityScopes
from fastapi.testclient import TestClient

def dep_b():
    return "b"

def dep_a(b: str = Depends(dep_b)):
    return f"a-{b}"

app = FastAPI()

@app.get("/test-security-1")
def test_security_1(a: str = Security(dep_a, scopes=["scope1"])):
    return {"result": a}

@app.get("/test-security-2")
def test_security_2(a: str = Security(dep_a, scopes=["scope2"])):
    return {"result": a}

@app.get("/test-depends")
def test_depends(a: str = Depends(dep_a)):
    return {"result": a}

client = TestClient(app)

def test_cache_scopes_propagation():
    # When we call different endpoints that use dep_a and dep_b with different scopes,
    # dep_b should be cached separately for each set of scopes if it's supposed to be.

    # We can check if they are cached by observing the number of times they are called.
    # Since we can't easily instrument the functions without modifying them,
    # we can use a mock or a counter.

    call_count = 0

    def dep_b_counter():
        nonlocal call_count
        call_count += 1
        return "b"

    def dep_a_counter(b: str = Depends(dep_b_counter)):
        return f"a-{b}"

    # Redefine app to use the counter
    app_counter = FastAPI()
    @app_counter.get("/s1")
    def s1(a: str = Security(dep_a_counter, scopes=["scope1"])):
        return {"res": a}

    @app_counter.get("/s2")
    def s2(a: str = Security(dep_a_counter, scopes=["scope2"])):
        return {"res": a}

    @app_counter.get("/d")
    def d(a: str = Depends(dep_a_counter)):
        return {"res": a}

    client_counter = TestClient(app_counter)

    # First calls: should increment counter
    client_counter.get("/s1") # dep_a(s1), dep_b(s1)
    client_counter.get("/s2") # dep_a(s2), dep_b(s2)
    client_counter.get("/d")   # dep_a(None), dep_b(None)

    initial_calls = call_count
    call_count = 0

    # Second calls: should use cache if cached correctly
    client_counter.get("/s1")
    client_counter.get("/s2")
    client_counter.get("/d")

    # If cached, call_count should be 0
    assert call_count == 0, f"Expected 0 calls due to cache, but got {call_count}"

def test_different_scopes_cache_separately():
    # This test verifies that dependencies with different scopes are NOT sharing the same cache entry.
    # Wait, if they are cached separately, then the first call to each scope should increment the counter.

    call_count = 0
    def dep_b_counter():
        nonlocal call_count
        call_count += 1
        return "b"

    def dep_a_counter(b: str = Depends(dep_b_counter)):
        return f"a-{b}"

    app_counter = FastAPI()
    @app_counter.get("/s1")
    def s1(a: str = Security(dep_a_counter, scopes=["scope1"])):
        return {"res": a}

    @app_counter.get("/s2")
    def s2(a: str = Security(dep_a_counter, scopes=["scope2"])):
        return {"res": a}

    client_counter = TestClient(app_counter)

    call_count = 0
    client_counter.get("/s1")
    # dep_a(scope1) called, dep_b(scope1) called. count = 1
    assert call_count == 1

    client_counter.get("/s2")
    # dep_a(scope2) called, dep_b(scope2) called. count = 2
    assert call_count == 2

    # Second calls
    call_count = 0
    client_counter.get("/s1")
    client_counter.get("/s2")
    assert call_count == 0

